import ReactDOM from 'react-dom';

const SearchResults = () => {
  // Use shouldComponentUpdate to prevent unnecessary re-renders
  shouldComponentUpdate(nextProps, nextState) {
    return nextProps.searchQuery !== this.props.searchQuery;
  }

